import torch

from tile_kernels.mhc.expand_kernel import expand_to_mhc_bwd_tl, expand_to_mhc_fwd_tl


class ExpandToMHCFn(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx: 'ExpandToMHCFn',
        hidden: torch.Tensor,
        mhc_mult: int,
        out: torch.Tensor | None,
    ) -> torch.Tensor:
        if out is None:
            out = hidden.new_empty(*hidden.shape[:-1], mhc_mult, hidden.shape[-1])
        assert hidden.is_contiguous()
        kernel = expand_to_mhc_fwd_tl(hidden.shape[-1], mhc_mult)
        kernel(hidden.flatten(0, -2), out.flatten(0, -3))
        return out

    @staticmethod
    def backward(ctx: 'ExpandToMHCFn', out_grad: torch.Tensor) -> torch.Tensor:
        hidden_grad = out_grad.new_empty(*out_grad.shape[:-2], out_grad.shape[-1])
        kernel = expand_to_mhc_bwd_tl(out_grad.shape[-1], out_grad.shape[-2])
        kernel(out_grad.flatten(0, -3), hidden_grad.flatten(0, -2))
        return hidden_grad, None, None


def expand_to_mhc(
    hidden: torch.Tensor,
    mhc_mult: int,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    return ExpandToMHCFn.apply(hidden, mhc_mult, out)

import torch

from tile_kernels.mhc.sinkhorn_kernel import _mhc_sinkhorn_bwd, _mhc_sinkhorn_fwd


class _SinkhornNormalize(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx: '_SinkhornNormalize',
        x: torch.Tensor,
        repeat: int,
        eps: float,
    ) -> torch.Tensor:
        hidden_size = x.shape[1]
        output = torch.empty_like(x)
        fwd_kernel = _mhc_sinkhorn_fwd(hidden_size, 1, repeat, eps)
        bwd_kernel = _mhc_sinkhorn_bwd(hidden_size, 32, repeat, eps)
        ctx.save_for_backward(x)
        ctx.bwd_kernel = bwd_kernel
        fwd_kernel(x, output)
        return output

    @staticmethod
    def backward(ctx: '_SinkhornNormalize', grad_output: torch.Tensor) -> tuple[torch.Tensor, None, None]:
        x = ctx.saved_tensors[0]
        grad_input = torch.empty_like(x)
        ctx.bwd_kernel(grad_output, x, grad_input)
        return grad_input, None, None


def sinkhorn_normalize(x: torch.Tensor, repeat: int = 10, eps: float = 1e-6) -> torch.Tensor:
    return _SinkhornNormalize.apply(x.contiguous().view(-1, *x.shape[-2:]), repeat, eps).view_as(x)

import torch

from tile_kernels.mhc.post_kernel import mhc_post_bwd, mhc_post_fwd


class MHCPost(torch.autograd.Function):
    @staticmethod
    def forward(
        ctx: 'MHCPost',
        x: torch.Tensor,
        residual: torch.Tensor,
        post_layer_mix: torch.Tensor,
        comb_res_mix: torch.Tensor,
        out: torch.Tensor | None,
    ) -> torch.Tensor:
        out = mhc_post_fwd(x, residual, post_layer_mix, comb_res_mix, out)
        ctx.save_for_backward(x, residual, post_layer_mix, comb_res_mix)
        return out

    @staticmethod
    def backward(
        ctx: 'MHCPost',
        d_o: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, None]:
        return *mhc_post_bwd(*ctx.saved_tensors, d_o), None


def mhc_post(
    x: torch.Tensor,
    residual: torch.Tensor,
    post_layer_mix: torch.Tensor,
    comb_res_mix: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    return MHCPost.apply(x, residual, post_layer_mix, comb_res_mix, out)

import tilelang
import torch
from tilelang import language as T


@tilelang.jit
def expand_to_mhc_fwd_tl(hidden: int, mhc_mult: int) -> tilelang.JITKernel:
    n = T.dynamic('num_tokens')
    h = hidden
    mhc = mhc_mult

    blk_n = 32
    blk_h = 128

    @T.prim_func
    def expand_to_mhc_fwd_kernel(
        x: T.Tensor[(n, h), T.bfloat16],
        o: T.Tensor[(n, mhc, h), T.bfloat16],
    ) -> None:
        with T.Kernel(T.ceildiv(n, blk_n), T.ceildiv(h, blk_h)) as (pid_i, pid_j):
            if n > 0:
                xl = T.alloc_fragment((blk_n, blk_h), T.bfloat16)
                T.copy(x[pid_i * blk_n, pid_j * blk_h], xl)
                for m in T.serial(mhc):
                    for ti, tj in T.Parallel(blk_n, blk_h):
                        i = pid_i * blk_n + ti
                        j = pid_j * blk_h + tj
                        if i < n and j < h:
                            o[i, m, j] = xl[ti, tj]

    return expand_to_mhc_fwd_kernel


@tilelang.jit
def expand_to_mhc_bwd_tl(hidden: int, mhc_mult: int) -> tilelang.JITKernel:
    n = T.dynamic('num_tokens')
    h = hidden
    mhc = mhc_mult

    blk_n = 32
    blk_h = 128

    @T.prim_func
    def expand_to_mhc_bwd_kernel(
        o_grad: T.Tensor[(n, mhc, h), T.bfloat16],
        x_grad: T.Tensor[(n, h), T.bfloat16],
    ) -> None:
        with T.Kernel(T.ceildiv(n, blk_n), T.ceildiv(h, blk_h)) as (pid_i, pid_j):
            if n > 0:
                xgl = T.alloc_fragment((blk_n, blk_h), T.float32)
                T.fill(xgl, 0)
                for m in T.serial(mhc):
                    for ti, tj in T.Parallel(blk_n, blk_h):
                        i = pid_i * blk_n + ti
                        j = pid_j * blk_h + tj
                        if i < n and j < h:
                            xgl[ti, tj] += o_grad[i, m, j]
                T.copy(xgl, x_grad[pid_i * blk_n, pid_j * blk_h])

    return expand_to_mhc_bwd_kernel
